window.VOICE = {"engine":"files:/home/user/skyde/video/seslendirme/Eslik","gain":1.25,"lines":[{"id":"e-hook","say":"Hiç duymadığın bir şarkıya bile, ikinci nakarata gelmeden eşlik etmeye başlıyorsun. İnanmıyorsan dene; bu melodiyi ilk kez duyacaksın.","at":0.1,"dur":7.979,"marks":[0,1.86,4.92,6.22]},{"id":"e-tekrar","say":"Şimdi bir daha çalıyorum. Bu sefer sen de içinden eşlik et.","at":17.529,"dur":3.023,"marks":[0,1.26]},{"id":"e-tamam","say":"Sonunu çalmadım... ama sen tamamladın, değil mi?","at":25.152,"dur":3.033,"marks":[0,1.42,2.48]},{"id":"e-neden","say":"Çünkü beynin şarkıyı sadece dinlemiyor, tahmin ediyor. Duyduğun binlerce şarkının kurallarını sen fark etmeden ezberledi; nakarat ikinci kez gelince onu çoktan kaydetmiş oluyor.","at":30.185,"dur":11.578,"marks":[0,2.7,3.88,8.06]},{"id":"e-keyif","say":"Tahminin tuttukça beynin seni ödüllendiriyor. Birlikte söylemek de yabancıları bile hızla yakınlaştırıyor; düğünde herkesin aynı şarkıya katılması boşuna değil.","at":42.413,"dur":9.531,"marks":[0,2.96,6.56]},{"id":"e-cta","say":"Sözleri bilmeden her şarkıya eşlik eden arkadaşına gönder. Bu videoya da eşlik etti, eminim.","at":52.744,"dur":6.262,"marks":[0,4.34,5.88]}],"audio":""};
